// Set do śledzenia unikalnych tytułów
const seenTitles = new Set();
const allNotes = [];

// Iterujemy po wszystkich itemach z HTTP Request Node
for (const item of $items()) { // $items() zwraca tablicę wszystkich wejść
  const tytul = item.json?.tytul;
  const tresc = item.json?.tresc;
  const data_powstania = item.json?.data_powstania;

  // Pomijamy puste pola
  if (!tytul || !tresc) continue;

  // Pomijamy duplikaty po tytule
  if (seenTitles.has(tytul)) continue;
  seenTitles.add(tytul);

  // Dodajemy obiekt do tablicy
  allNotes.push({ tytul, tresc, data_powstania });
}

// Zwracamy wynik z endSignal
return [
  {
    json: {
      combinedNotes: allNotes,
      endSignal: "ZAKOŃCZ"
    }
  }
];

// 1. Pobieramy bieżącą datę w strefie Europe/Warsaw
const now = new Date();
const optionsDate = { timeZone: "Europe/Warsaw", day: "2-digit", month: "2-digit", year: "numeric" };
const optionsTime = { timeZone: "Europe/Warsaw", hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false };

// Format daty i godziny
const datePart = now.toLocaleDateString("pl-PL", optionsDate).replace(/\//g, ".");
const timePart = now.toLocaleTimeString("pl-PL", optionsTime);

// Tworzymy tytuł w formacie DD.MM.YYYY, HH:MM:SS
const title = `${datePart}, ${timePart}`;

// 2. Pobieramy output od poprzedniego node'a (pierwszy item)
let output = $input.first().json.output || "";

// 3. Zamieniamy separator "---" na <hr /> i podwójne nowe linie na <p>
let formattedOutput = output
  .replace(/---/g, "<hr />")
  .split(/\n{2,}/) // każde dwa lub więcej enterów traktujemy jako akapit
  .map(block => block.trim())
  .filter(Boolean)
  .map(block => `<p>${block}</p>`)
  .join("");

// 4. Zwracamy title i sformatowany output
return [
  {
    json: {
      title,
      output: formattedOutput
    }
  }
];

const raw = $('Code').first().json.output;

// 1. Usuń tagi HTML
let clean = raw
  .replace(/<p>/g, '\n')
  .replace(/<\/p>/g, '\n')
  .replace(/<hr\s*\/?>/g, '\n--------------------------------\n')
  .replace(/<[^>]+>/g, '') // usuwa wszystkie pozostałe tagi
  .replace(/\n{2,}/g, '\n\n'); // normalizacja nowych linii

// 2. Dodaj odstęp po tytułach (linie zaczynające się od ###)
clean = clean.replace(/^###\s*(.*)$/gm, "### $1\n");

// 3. Dodaj wcięcie do akapitów (linie nie będące tytułem ani separatorem)
clean = clean.replace(/^(?!###|[-]{32}\n)(.+)$/gm, "\t$1");

// 4. Trim całości
let formatted = clean.trim();

// 5. Dodaj disclaimer przed hashtagami
formatted = formatted.replace(
  /(#Bitcoin.*)$/s,
  "Artykuł jest wynikiem działania automatyzacji opartej na AI, która podsumowuje najważniejsze informacje z ostatnich 8 godzin z serwisów Coindesk i Cointelegraph – Nie jest to doskonałe - Uwagi mile widziane - Zapraszam do kontaktu🙌\n\n$1"
);

return {
  json: {
    output: formatted
  }
};
